// App-owned interface text. Columns: English, Japanese, Korean. Chinese is the key.
// Compiled into the core so signed app and SwiftPM builds use the same catalog.
extension L10n {
    static let catalog: [String: [String]] = [
        "检查更新…": ["Check for Updates…", "アップデートを確認…", "업데이트 확인…"],
        "自动检查更新": ["Automatically Check for Updates", "アップデートを自動確認", "자동으로 업데이트 확인"],
        "自动下载并安装更新": ["Automatically Download and Install Updates", "アップデートを自動ダウンロードしてインストール", "업데이트 자동 다운로드 및 설치"],
        "更新服务暂不可用": ["Updates Are Unavailable", "アップデートを利用できません", "업데이트를 사용할 수 없습니다"],
        "请从已安装的应用中检查更新。": ["Check for updates from the installed application.", "インストール済みのアプリからアップデートを確認してください。", "설치된 앱에서 업데이트를 확인해 주세요."],
        "尚未使用历史记录": ["History has not been used yet", "履歴はまだ使用されていません", "아직 기록을 사용하지 않았습니다"],
        "尚未接收回车": ["Return has not been received yet", "Return キーの入力はまだありません", "아직 Return 키 입력이 없습니다"],
        "收藏库": ["Favorites", "お気に入り", "즐겨찾기"],
        "正在迁移存储，请稍后收藏。": ["Storage is being moved. Please wait before adding favorites.", "保存場所を移行中です。完了後にお気に入りに追加してください。", "저장 위치를 이동하고 있습니다. 완료 후 즐겨찾기에 추가해 주세요."],
        "位置保存失败，请检查安装目录的写入权限。": ["Could not save the window position. Check write permissions for the installation folder.", "ウインドウの位置を保存できませんでした。インストール先の書き込み権限を確認してください。", "창 위치를 저장하지 못했습니다. 설치 폴더의 쓰기 권한을 확인해 주세요."],
        "剪贴板": ["Clipboard", "クリップボード", "클립보드"],
        "剪贴板 · {0}": ["Clipboard · {0}", "クリップボード · {0}", "클립보드 · {0}"],
        "暂时无法保存，记录仍可使用。请打开“数据与恢复”重试。": ["Unable to save right now. Your history is still available. Open “Data & Recovery” to retry.", "現在保存できません。履歴は引き続き使用できます。「データと復元」から再試行してください。", "지금은 저장할 수 없습니다. 기록은 계속 사용할 수 있습니다. “데이터 및 복구”에서 다시 시도해 주세요."],
        "迁移期间新复制暂存于内存，完成后保存。": ["New copies are kept in memory during the move and saved when it finishes.", "移行中の新しいコピーはメモリに保持され、完了後に保存されます。", "이동 중 새로 복사한 내용은 메모리에 보관되며 완료 후 저장됩니다."],
        "记录暂存于本次运行。打开“数据与恢复”可重试保存。": ["History is available for this session. Open “Data & Recovery” to retry saving.", "履歴は今回の起動中のみ保持されています。「データと復元」から保存を再試行できます。", "기록은 현재 실행 중에만 유지됩니다. “데이터 및 복구”에서 저장을 다시 시도할 수 있습니다."],
        "保存暂未完成，记录仍在。打开“数据与恢复”重试。": ["Saving has not finished. Your history is still available. Retry in “Data & Recovery”.", "保存が完了していません。履歴は保持されています。「データと復元」から再試行してください。", "저장이 완료되지 않았습니다. 기록은 유지됩니다. “데이터 및 복구”에서 다시 시도해 주세요."],
        "数据由更新版本创建。原文件已保留，请使用更新版本打开。": ["This data was created by a newer version. Original files are preserved. Open with a newer version.", "新しいバージョンで作成されたデータです。元のファイルは保持されています。新しいバージョンで開いてください。", "새 버전에서 생성된 데이터입니다. 원본 파일은 보존되어 있습니다. 새 버전으로 열어 주세요."],
        "部分数据暂时无法读取，原文件已保留。打开“数据与恢复”处理。": ["Some data could not be read. Original files are preserved. Open “Data & Recovery”.", "一部のデータを読み込めません。元のファイルは保持されています。「データと復元」を開いてください。", "일부 데이터를 읽을 수 없습니다. 원본 파일은 보존되어 있습니다. “데이터 및 복구”를 열어 주세요."],
        "已保存，可以继续使用。": ["Saved. You can continue using the app.", "保存しました。引き続き使用できます。", "저장했습니다. 계속 사용할 수 있습니다."],
        "暂时无法保存，记录仍在本次运行中。请确认磁盘空间和目录写入权限后重试。": ["Unable to save. History remains available in this session. Check disk space and folder write permissions, then retry.", "保存できません。履歴は今回の起動中は使用できます。ディスクの空き容量とフォルダの書き込み権限を確認し、再試行してください。", "저장할 수 없습니다. 현재 실행 중에는 기록을 사용할 수 있습니다. 디스크 여유 공간과 폴더 쓰기 권한을 확인한 후 다시 시도해 주세요."],
        "数据目录不可用，请将应用放在可写目录后重启。": ["The data folder is unavailable. Move the app to a writable folder and restart it.", "データフォルダを利用できません。書き込み可能なフォルダにアプリを移動して再起動してください。", "데이터 폴더를 사용할 수 없습니다. 앱을 쓰기 가능한 폴더로 이동한 후 다시 실행해 주세요."],
        "退出剪贴板": ["Quit ClipboardBoard", "ClipboardBoard を終了", "ClipboardBoard 종료"],
        "编辑": ["Edit", "編集", "편집"],
        "剪切": ["Cut", "カット", "오려두기"],
        "复制": ["Copy", "コピー", "복사"],
        "粘贴": ["Paste", "ペースト", "붙여넣기"],
        "全选": ["Select All", "すべてを選択", "모두 선택"],
        "{0} 未注册，可从菜单栏重新设置快捷键。": ["{0} is not registered. Configure a shortcut from the menu bar.", "{0} は登録されていません。メニューバーからショートカットを設定してください。", "{0} 단축키가 등록되지 않았습니다. 메뉴 막대에서 단축키를 설정해 주세요."],
        "未粘贴：请点击“去授权”，允许辅助功能后再使用。": ["Not pasted. Click “Grant Access” and allow Accessibility access first.", "ペーストしていません。「アクセスを許可」をクリックしてアクセシビリティを許可してください。", "붙여넣지 않았습니다. 먼저 “접근 허용”을 클릭하여 손쉬운 사용 접근을 허용해 주세요."],
        "未粘贴：请先点击目标输入框，再按 {0} 选择记录。": ["Not pasted. Click the target text field, then press {0} to select an entry.", "ペーストしていません。入力先をクリックし、{0} を押して履歴を選択してください。", "붙여넣지 않았습니다. 대상 입력란을 클릭한 다음 {0} 키를 눌러 항목을 선택해 주세요."],
        "请松开 ⌥、⌘ 和回车键，再按一次回车粘贴。": ["Release ⌥, ⌘, and Return, then press Return again to paste.", "⌥、⌘、Return キーを放してから、もう一度 Return キーを押してペーストしてください。", "⌥, ⌘ 및 Return 키에서 손을 뗀 다음 Return 키를 다시 눌러 붙여넣어 주세요."],
        "等待粘贴时发生了新的复制，请重新选择历史记录。": ["New content was copied while waiting to paste. Select a history entry again.", "ペーストの待機中に新しい内容がコピーされました。履歴を選択し直してください。", "붙여넣기를 기다리는 동안 새 내용이 복사되었습니다. 기록 항목을 다시 선택해 주세요."],
        "无法使用这条记录：文件可能已移动，或内容已损坏。": ["This entry cannot be used. Its files may have moved, or its content may be damaged.", "この履歴は使用できません。ファイルが移動されたか、内容が破損している可能性があります。", "이 항목을 사용할 수 없습니다. 파일이 이동되었거나 내용이 손상되었을 수 있습니다."],
        "目标应用未及时确认，请先检查输入框，避免重复粘贴。": ["The target app did not respond in time. Check the text field before retrying to avoid duplicate pastes.", "入力先のアプリが時間内に応答しませんでした。重複ペーストを防ぐため、再試行前に入力欄を確認してください。", "대상 앱이 제때 응답하지 않았습니다. 중복 붙여넣기를 방지하려면 다시 시도하기 전에 입력란을 확인해 주세요."],
        "打开历史记录    {0}": ["Open History    {0}", "履歴を開く    {0}", "기록 열기    {0}"],
        "打开收藏库": ["Open Favorites", "お気に入りを開く", "즐겨찾기 열기"],
        "存储位置…": ["Storage Location…", "保存場所…", "저장 위치…"],
        "自定义快捷键…（{0}）": ["Keyboard Shortcut… ({0})", "キーボードショートカット…（{0}）", "키보드 단축키… ({0})"],
        "历史记录上限：{0} 条…": ["History Limit: {0}…", "履歴の上限：{0} 件…", "기록 한도: {0}개…"],
        "完整预览选项…": ["Preview Options…", "プレビュー設定…", "미리보기 설정…"],
        "登录时自动启动": ["Launch at Login", "ログイン時に起動", "로그인 시 실행"],
        "继续记录": ["Resume Recording", "記録を再開", "기록 재개"],
        "暂停记录": ["Pause Recording", "記録を一時停止", "기록 일시 정지"],
        "清空全部历史": ["Clear All History", "履歴をすべて消去", "모든 기록 지우기"],
        "辅助功能权限…": ["Accessibility Access…", "アクセシビリティのアクセス許可…", "손쉬운 사용 접근 권한…"],
        "粘贴诊断…": ["Paste Diagnostics…", "ペーストの診断…", "붙여넣기 진단…"],
        "打开数据目录": ["Open Data Folder", "データフォルダを開く", "데이터 폴더 열기"],
        "数据与恢复…": ["Data & Recovery…", "データと復元…", "데이터 및 복구…"],
        "数据与恢复…（需要处理）": ["Data & Recovery… (Action Needed)", "データと復元…（要確認）", "데이터 및 복구… (조치 필요)"],
        "开发版": ["Development", "開発版", "개발 버전"],
        "剪贴板 {0}": ["ClipboardBoard {0}", "ClipboardBoard {0}", "ClipboardBoard {0}"],
        "粘贴诊断": ["Paste Diagnostics", "ペーストの診断", "붙여넣기 진단"],
        "已允许": ["Allowed", "許可済み", "허용됨"],
        "未允许": ["Not Allowed", "未許可", "허용되지 않음"],
        "无": ["None", "なし", "없음"],
        "版本：{0} · {1}\n辅助功能：{2}\n模拟按键：{3}\n目标程序：{4}\n回车路径：{5}\n最近状态：{6}": ["Version: {0} · {1}\nAccessibility: {2}\nSimulated Keystrokes: {3}\nTarget App: {4}\nReturn Key Route: {5}\nLatest Status: {6}", "バージョン：{0} · {1}\nアクセシビリティ：{2}\nキー入力の送信：{3}\n入力先アプリ：{4}\nReturn キーの処理経路：{5}\n直近の状態：{6}", "버전: {0} · {1}\n손쉬운 사용: {2}\n키 입력 시뮬레이션: {3}\n대상 앱: {4}\nReturn 키 처리 경로: {5}\n최근 상태: {6}"],
        "关闭": ["Close", "閉じる", "닫기"],
        "收藏正在保存，请完成后再迁移。": ["Favorites are being saved. Wait before moving storage.", "お気に入りを保存中です。完了後に保存場所を移行してください。", "즐겨찾기를 저장하고 있습니다. 완료 후 저장 위치를 이동해 주세요."],
        "当前数据尚未正常保存，请先通过“数据与恢复”恢复原位置。": ["Data has not been saved successfully. Restore the current location through “Data & Recovery” first.", "データを正常に保存できていません。先に「データと復元」で現在の保存場所を復旧してください。", "데이터가 정상적으로 저장되지 않았습니다. 먼저 “데이터 및 복구”에서 현재 위치를 복구해 주세요."],
        "数据已保存在本机": ["Data Is Saved on This Mac", "データはこの Mac に保存されています", "데이터가 이 Mac에 저장되어 있습니다"],
        "让记录恢复正常保存": ["Restore History Saving", "履歴の保存を復旧", "기록 저장 복구"],
        "当前没有需要处理的问题。": ["There are no issues to resolve.", "対処が必要な問題はありません。", "조치가 필요한 문제가 없습니다."],
        "\n\n先尝试“重试”。若文件损坏，可保留原文件后重建；可读记录和本次复制会保留。恢复副本只供手动取回，不会自动导回已删除内容。": ["\n\nTry “Retry” first. Damaged files can be preserved before rebuilding. Readable entries and copies from this session are kept. Recovery copies are for manual retrieval only; deleted content is never restored automatically.", "\n\nまず「再試行」をお試しください。ファイルが破損している場合は、元のファイルを保持して再作成できます。読み取り可能な履歴と今回のコピーは保持されます。復元用コピーは手動で取り出すためのもので、削除済みの内容が自動で戻ることはありません。", "\n\n먼저 “다시 시도”를 눌러 주세요. 손상된 파일은 원본을 보존한 후 다시 만들 수 있습니다. 읽을 수 있는 기록과 이번 실행에서 복사한 내용은 유지됩니다. 복구 사본은 수동 복원용이며, 삭제한 내용이 자동으로 복원되지는 않습니다."],
        "完成": ["Done", "完了", "완료"],
        "重试": ["Retry", "再試行", "다시 시도"],
        "保留损坏文件并重建…": ["Preserve Damaged Files and Rebuild…", "破損ファイルを保持して再作成…", "손상된 파일 보존 후 다시 만들기…"],
        "取消": ["Cancel", "キャンセル", "취소"],
        "保留原文件，再恢复记录功能？": ["Preserve Original Files and Restore History?", "元のファイルを保持して履歴機能を復旧しますか？", "원본 파일을 보존하고 기록 기능을 복구할까요?"],
        "只重建无法解析的文件。原文件会保存在数据目录的 Recovery 文件夹，可读历史和本次复制会保留。更新版本的数据不会被重建。": ["Only unreadable files are rebuilt. Originals are kept in the data folder’s Recovery folder. Readable history and copies from this session are preserved. Data from newer versions is not rebuilt.", "解析できないファイルのみ再作成します。元のファイルはデータフォルダ内の Recovery に保持されます。読み取り可能な履歴と今回のコピーは保持されます。新しいバージョンのデータは再作成しません。", "분석할 수 없는 파일만 다시 만듭니다. 원본은 데이터 폴더의 Recovery 폴더에 보존됩니다. 읽을 수 있는 기록과 이번 실행에서 복사한 내용은 유지됩니다. 새 버전의 데이터는 다시 만들지 않습니다."],
        "保留并恢复": ["Preserve and Restore", "保持して復旧", "보존 및 복구"],
        "数据由更新版本创建，请更新应用。原文件没有被修改。": ["This data was created by a newer version. Update the app. Original files have not been changed.", "新しいバージョンで作成されたデータです。アプリを更新してください。元のファイルは変更されていません。", "새 버전에서 생성된 데이터입니다. 앱을 업데이트해 주세요. 원본 파일은 변경되지 않았습니다."],
        "恢复未完成，原文件仍保留。请检查磁盘空间和目录写入权限。": ["Recovery did not finish. Original files are preserved. Check disk space and folder write permissions.", "復旧が完了しませんでした。元のファイルは保持されています。ディスクの空き容量とフォルダの書き込み権限を確認してください。", "복구가 완료되지 않았습니다. 원본 파일은 보존되어 있습니다. 디스크 여유 공간과 폴더 쓰기 권한을 확인해 주세요."],
        "记录功能已恢复，原文件已保留在 Recovery 中。": ["History is working again. Original files are preserved in Recovery.", "履歴機能を復旧しました。元のファイルは Recovery に保持されています。", "기록 기능을 복구했습니다. 원본 파일은 Recovery에 보존되어 있습니다."],
        "保留多少条历史？": ["How Many History Entries Should Be Kept?", "履歴を何件保持しますか？", "기록을 몇 개 보관할까요?"],
        "默认 10 条，可设置 1–50 条。超出上限时自动移除最早记录；调小后立即生效。": ["Default: 10. Range: 1–50. The oldest entries are removed when the limit is exceeded. Lowering the limit takes effect immediately.", "初期値は 10 件、設定範囲は 1～50 件です。上限を超えると最も古い履歴から削除します。上限を減らすとすぐに適用されます。", "기본값은 10개이며 1~50개로 설정할 수 있습니다. 한도를 초과하면 가장 오래된 기록부터 삭제됩니다. 한도를 줄이면 즉시 적용됩니다."],
        "保存": ["Save", "保存", "저장"],
        "历史记录数量上限，1 到 50": ["History entry limit, 1 to 50", "履歴の上限、1～50 件", "기록 항목 한도, 1~50개"],
        "请输入 1 到 50 之间的整数。": ["Enter a whole number from 1 to 50.", "1～50 の整数を入力してください。", "1~50 사이의 정수를 입력해 주세요."],
        "设置保存失败，请检查安装目录是否可写。": ["Could not save settings. Check that the installation folder is writable.", "設定を保存できません。インストール先に書き込めるか確認してください。", "설정을 저장하지 못했습니다. 설치 폴더에 쓸 수 있는지 확인해 주세요."],
        "收藏库尚未就绪。": ["Favorites are not ready yet.", "お気に入りはまだ準備できていません。", "즐겨찾기가 아직 준비되지 않았습니다."],
        "当前存储不可用，请通过“数据与恢复”重试。": ["Storage is unavailable. Retry through “Data & Recovery”.", "保存先を利用できません。「データと復元」から再試行してください。", "저장소를 사용할 수 없습니다. “데이터 및 복구”에서 다시 시도해 주세요."],
        "收藏由更新版本创建，请使用更新版本打开。原文件已保留。": ["Favorites were created by a newer version. Open with a newer version. Original files are preserved.", "お気に入りは新しいバージョンで作成されています。新しいバージョンで開いてください。元のファイルは保持されています。", "즐겨찾기가 새 버전에서 생성되었습니다. 새 버전으로 열어 주세요. 원본 파일은 보존되어 있습니다."],
        "正在迁移存储，新复制暂存于内存，完成后保存。": ["Moving storage. New copies are kept in memory and saved when the move finishes.", "保存場所を移行中です。新しいコピーはメモリに保持され、完了後に保存されます。", "저장 위치를 이동하고 있습니다. 새로 복사한 내용은 메모리에 보관되며 완료 후 저장됩니다."],
        "收藏正在保存，请稍后操作。": ["Favorites are being saved. Please wait.", "お気に入りを保存中です。しばらくお待ちください。", "즐겨찾기를 저장하고 있습니다. 잠시 기다려 주세요."],
        "已取消收藏，普通历史仍保留。": ["Removed from favorites. Regular history is preserved.", "お気に入りから削除しました。通常の履歴は保持されています。", "즐겨찾기에서 제거했습니다. 일반 기록은 유지됩니다."],
        "已收藏到“未分类”，可在收藏库中整理。": ["Added to “Unfiled”. Organize it in Favorites.", "「未分類」に追加しました。お気に入りで整理できます。", "“미분류”에 추가했습니다. 즐겨찾기에서 정리할 수 있습니다."],
        "收藏预览": ["Favorites Preview", "お気に入りのプレビュー", "즐겨찾기 미리보기"],
        "全部收藏": ["All Favorites", "すべてのお気に入り", "모든 즐겨찾기"],
